import { describe, it, expect, jest, beforeEach } from '@jest/globals';
import { 
  extractMaterials, 
  generateMaterialList,
  updateMaterialList,
  generateMaterialDetails,
  zipWeeklyPrintables
} from '../../src/services/materialGenerator';

describe('MaterialGenerator Unit Tests', () => {
  describe('extractMaterials', () => {
    it('should extract materials from simple header format', () => {
      const note = `
        Today we will learn about fractions.
        Materials: paper, pencils, fraction blocks
        Remember to bring your notebooks.
      `;

      const result = extractMaterials(note);
      expect(result).toContain('paper');
      expect(result).toContain('pencils');
      expect(result).toContain('fraction blocks');
    });

    it('should extract materials from list format', () => {
      const note = `
        Materials:
        - Whiteboard markers
        - Chart paper
        - Sticky notes
        - Timer
      `;

      const result = extractMaterials(note);
      expect(result).toContain('Whiteboard markers');
      expect(result).toContain('Chart paper');
      expect(result).toContain('Sticky notes');
      expect(result).toContain('Timer');
    });

    it('should handle materials with asterisk bullets', () => {
      const note = `
        Materials needed:
        * Colored pencils
        * Ruler
        * Construction paper
      `;

      const result = extractMaterials(note);
      expect(result).toContain('Colored pencils');
      expect(result).toContain('Ruler');
      expect(result).toContain('Construction paper');
    });

    it('should handle comma-separated materials in header', () => {
      const note = `
        Materials: glue sticks, scissors, colored paper, markers
      `;

      const result = extractMaterials(note);
      expect(result).toContain('glue sticks');
      expect(result).toContain('scissors');
      expect(result).toContain('colored paper');
      expect(result).toContain('markers');
    });

    it('should handle semicolon-separated materials', () => {
      const note = `
        Materials: calculator; graph paper; protractor; compass
      `;

      const result = extractMaterials(note);
      expect(result).toContain('calculator');
      expect(result).toContain('graph paper');
      expect(result).toContain('protractor');
      expect(result).toContain('compass');
    });

    it('should handle case-insensitive materials header', () => {
      const testCases = [
        'Materials: paper',
        'MATERIALS: paper',
        'materials: paper',
        'Material: paper',
        'MATERIAL: paper',
      ];

      testCases.forEach((testCase) => {
        const result = extractMaterials(testCase);
        expect(result).toContain('paper');
      });
    });

    it('should handle materials header with colon variations', () => {
      const testCases = [
        'Materials: paper',
        'Materials paper', // No colon
        'Materials needed: paper',
      ];

      testCases.forEach((testCase) => {
        const result = extractMaterials(testCase);
        expect(result).toContain('paper');
      });
    });

    it('should remove duplicates', () => {
      const note = `
        Materials: paper, pencils, paper
        Additional materials:
        - paper
        - pencils
        - eraser
      `;

      const result = extractMaterials(note);
      const paperCount = result.filter((item) => item === 'paper').length;
      const pencilsCount = result.filter((item) => item === 'pencils').length;

      expect(paperCount).toBe(1);
      expect(pencilsCount).toBe(1);
      expect(result).toContain('eraser');
    });

    it('should trim whitespace from extracted materials', () => {
      const note = `
        Materials:   paper  ,  pencils   , markers  
      `;

      const result = extractMaterials(note);
      expect(result).toContain('paper');
      expect(result).toContain('pencils');
      expect(result).toContain('markers');

      // Should not contain items with extra whitespace
      expect(result).not.toContain(' paper ');
      expect(result).not.toContain('  pencils  ');
    });

    it('should handle empty notes', () => {
      const result = extractMaterials('');
      expect(result).toEqual([]);
    });

    it('should handle notes without materials section', () => {
      const note = `
        Today we will learn about photosynthesis.
        Students should take notes on the process.
        Homework is chapter 4.
      `;

      const result = extractMaterials(note);
      expect(result).toEqual([]);
    });

    it('should handle mixed format with multiple materials sections', () => {
      const note = `
        Materials: paper, pencils
        
        Today's lesson plan...
        
        Additional materials needed:
        - Calculators
        - Graph paper
        
        Extra supplies: rulers, erasers
      `;

      const result = extractMaterials(note);
      expect(result).toContain('paper');
      expect(result).toContain('pencils');
      expect(result).toContain('Calculators');
      expect(result).toContain('Graph paper');
      expect(result).toContain('rulers');
      expect(result).toContain('erasers');
    });

    it('should handle materials with numbers and special characters', () => {
      const note = `
        Materials:
        - 30 cm ruler
        - #2 pencils
        - 8.5x11 paper
        - 3-ring binder
      `;

      const result = extractMaterials(note);
      expect(result).toContain('30 cm ruler');
      expect(result).toContain('#2 pencils');
      expect(result).toContain('8.5x11 paper');
      expect(result).toContain('3-ring binder');
    });

    it('should handle materials with parenthetical information', () => {
      const note = `
        Materials:
        - Markers (various colors)
        - Paper plates (small size)
        - Glue (washable)
      `;

      const result = extractMaterials(note);
      expect(result).toContain('Markers (various colors)');
      expect(result).toContain('Paper plates (small size)');
      expect(result).toContain('Glue (washable)');
    });

    it('should filter out empty items', () => {
      const note = `
        Materials: paper,  , pencils, , markers
      `;

      const result = extractMaterials(note);
      expect(result).toEqual(['paper', 'pencils', 'markers']);
      expect(result).not.toContain('');
      expect(result).not.toContain(' ');
    });

    it('should handle notes with Windows line endings', () => {
      const note = 'Materials:\r\n- paper\r\n- pencils';

      const result = extractMaterials(note);
      expect(result).toContain('paper');
      expect(result).toContain('pencils');
    });

    it('should handle French materials section', () => {
      const note = `
        Matériel: papier, crayons, règle
        Aujourd'hui nous allons étudier...
      `;

      // The function might not handle French, but let's test behavior
      const result = extractMaterials(note);
      // This test documents current behavior - may need updating if French support is added
      expect(Array.isArray(result)).toBe(true);
    });

    it('should handle very long material lists', () => {
      const materials = Array.from({ length: 50 }, (_, i) => `item${i + 1}`);
      const note = `Materials: ${materials.join(', ')}`;

      const result = extractMaterials(note);
      expect(result.length).toBe(50);
      expect(result).toContain('item1');
      expect(result).toContain('item25');
      expect(result).toContain('item50');
    });

    it('should handle materials with nested lists', () => {
      const note = `
        Materials:
        - Art supplies:
          - Crayons
          - Markers
        - Paper
      `;

      const result = extractMaterials(note);
      // Should handle the primary list items
      expect(result).toContain('Art supplies:');
      expect(result).toContain('Paper');

      // Nested items might not be captured (depends on implementation)
      // This test documents the current behavior
    });
  });

  describe('generateMaterialList (Disabled Function)', () => {
    beforeEach(() => {
      // Mock console.warn to avoid noise in test output
      jest.spyOn(console, 'warn').mockImplementation();
    });

    afterEach(() => {
      jest.restoreAllMocks();
    });

    it('should return empty array and log warning', async () => {
      const weekStart = '2024-01-15';
      const result = await generateMaterialList(weekStart);

      expect(result).toEqual([]);
      expect(console.warn).toHaveBeenCalledWith(
        'generateMaterialList is disabled - legacy models removed'
      );
    });

    it('should handle different week start formats', async () => {
      const testDates = [
        '2024-01-01',
        '2024-12-31', 
        '2023-02-28',
        '2024-02-29', // Leap year
      ];

      for (const date of testDates) {
        const result = await generateMaterialList(date);
        expect(result).toEqual([]);
        expect(console.warn).toHaveBeenCalled();
      }
    });

    it('should handle invalid date formats gracefully', async () => {
      const invalidDates = [
        'invalid-date',
        '2024-13-01', // Invalid month
        '2024-01-32', // Invalid day
        '', // Empty string
      ];

      for (const date of invalidDates) {
        const result = await generateMaterialList(date);
        expect(result).toEqual([]);
      }
    });

    it('should handle null and undefined inputs', async () => {
      const result1 = await generateMaterialList(null as any);
      const result2 = await generateMaterialList(undefined as any);

      expect(result1).toEqual([]);
      expect(result2).toEqual([]);
    });
  });

  describe('updateMaterialList (Disabled Function)', () => {
    beforeEach(() => {
      jest.spyOn(console, 'warn').mockImplementation();
    });

    afterEach(() => {
      jest.restoreAllMocks();
    });

    it('should complete without error and log warning', async () => {
      const weekStart = '2024-01-15';
      
      await expect(updateMaterialList(weekStart)).resolves.toBeUndefined();
      
      expect(console.warn).toHaveBeenCalledWith(
        expect.stringContaining('updateMaterialList is disabled - MaterialList model archived'),
        expect.arrayContaining([])
      );
    });

    it('should log the week start date in warning', async () => {
      const weekStart = '2024-03-25';
      await updateMaterialList(weekStart);

      expect(console.warn).toHaveBeenCalledWith(
        expect.stringContaining(`Items for ${weekStart}:`),
        expect.any(Array)
      );
    });

    it('should handle concurrent calls', async () => {
      const weekStart = '2024-01-15';
      const promises = [
        updateMaterialList(weekStart),
        updateMaterialList(weekStart),
        updateMaterialList(weekStart),
      ];

      await expect(Promise.all(promises)).resolves.toEqual([
        undefined,
        undefined,
        undefined,
      ]);
    });
  });

  describe('generateMaterialDetails (Disabled Function)', () => {
    beforeEach(() => {
      jest.spyOn(console, 'warn').mockImplementation();
    });

    afterEach(() => {
      jest.restoreAllMocks();
    });

    it('should return empty array and log warning', async () => {
      const weekStart = '2024-01-15';
      const result = await generateMaterialDetails(weekStart);

      expect(result).toEqual([]);
      expect(console.warn).toHaveBeenCalledWith(
        'generateMaterialDetails is disabled - legacy models removed'
      );
    });

    it('should return consistent empty structure', async () => {
      const result = await generateMaterialDetails('2024-01-01');

      expect(Array.isArray(result)).toBe(true);
      expect(result.length).toBe(0);
    });

    it('should handle multiple calls efficiently', async () => {
      const start = Date.now();
      
      const promises = Array.from({ length: 100 }, (_, i) => 
        generateMaterialDetails(`2024-01-${String(i + 1).padStart(2, '0')}`)
      );
      
      const results = await Promise.all(promises);
      const duration = Date.now() - start;

      expect(results.every(result => Array.isArray(result) && result.length === 0)).toBe(true);
      expect(duration).toBeLessThan(1000); // Should be very fast
    });
  });

  describe('zipWeeklyPrintables (Disabled Function)', () => {
    beforeEach(() => {
      jest.spyOn(console, 'warn').mockImplementation();
    });

    afterEach(() => {
      jest.restoreAllMocks();
    });

    it('should return empty buffer and log warning', async () => {
      const weekStart = '2024-01-15';
      const result = await zipWeeklyPrintables(weekStart);

      expect(Buffer.isBuffer(result)).toBe(true);
      expect(result.length).toBe(0);
      expect(console.warn).toHaveBeenCalledWith(
        'zipWeeklyPrintables is disabled - legacy models removed'
      );
    });

    it('should return valid empty buffer', async () => {
      const result = await zipWeeklyPrintables('2024-01-01');

      expect(result).toBeInstanceOf(Buffer);
      expect(result.toString()).toBe('');
      expect(result.byteLength).toBe(0);
    });

    it('should handle different week start formats consistently', async () => {
      const dates = ['2024-01-01', '2024-06-15', '2024-12-31'];
      
      for (const date of dates) {
        const result = await zipWeeklyPrintables(date);
        expect(Buffer.isBuffer(result)).toBe(true);
        expect(result.length).toBe(0);
      }
    });

    it('should be safe for file operations', async () => {
      const result = await zipWeeklyPrintables('2024-01-15');
      
      // Should return a buffer (empty since function is disabled)
      expect(result).toBeInstanceOf(Buffer);
      expect(result.length).toBe(0);
    });
  });

  describe('Error Handling and Edge Cases', () => {
    describe('extractMaterials error scenarios', () => {
      it('should handle extremely long text inputs', () => {
        const longText = 'Materials: ' + 'item'.repeat(10000);
        
        const start = Date.now();
        const result = extractMaterials(longText);
        const duration = Date.now() - start;

        expect(result).toHaveLength(1);
        expect(result[0]).toBe('item'.repeat(10000));
        expect(duration).toBeLessThan(1000); // Should complete reasonably fast
      });

      it('should handle text with many special characters', () => {
        const specialText = `
          Materials: 🎨 art supplies, 📏 ruler (30cm), #2 pencils ✏️
          Additional materials:
          - 100% cotton paper
          - Markers (washable) @$2.99
          - Glue sticks & tape
        `;

        const result = extractMaterials(specialText);
        
        expect(result).toContain('🎨 art supplies');
        expect(result).toContain('📏 ruler (30cm)');
        expect(result).toContain('#2 pencils ✏️');
        expect(result).toContain('100% cotton paper');
        expect(result).toContain('Markers (washable) @$2.99');
        expect(result).toContain('Glue sticks & tape');
      });

      it('should handle mixed line endings correctly', () => {
        const mixedLineEndings = 'Materials:\r\n- paper\n- pencils\r\n\r- markers\n\n- crayons';

        const result = extractMaterials(mixedLineEndings);

        expect(result).toContain('paper');
        expect(result).toContain('pencils');
        expect(result).toContain('markers');
        expect(result).toContain('crayons');
      });

      it.skip('should handle malformed bullet points', () => {
        const malformed = `
          Materials:
          -paper (missing space)
          * pencils (different bullet)
          +markers (plus sign)
          >crayons (arrow)
          ・rulers (Japanese bullet)
        `;

        const result = extractMaterials(malformed);
        
        // Should only pick up properly formatted bullets
        expect(result).toContain('pencils (different bullet)');
        // Other malformed items might not be captured depending on implementation
      });

      it('should handle recursive material sections', () => {
        const recursive = `
          Materials: main supplies
          Section 1:
            Materials: section 1 supplies
            - item 1
          Section 2:
            Materials needed: section 2 supplies
            - item 2
        `;

        const result = extractMaterials(recursive);

        expect(result).toContain('main supplies');
        expect(result).toContain('section 1 supplies');
        expect(result).toContain('section 2 supplies');
        expect(result).toContain('item 1');
        expect(result).toContain('item 2');
      });

      it.skip('should handle materials with complex formatting', () => {
        const complex = `
          Materials:
          - Red markers (pack of 12) - $5.99
          - Blue construction paper: 
            * 8.5x11 size
            * 50 sheets per pack
          - Scissors (safety, rounded tips)
            WARNING: Adult supervision required
        `;

        const result = extractMaterials(complex);

        expect(result).toContain('Red markers (pack of 12) - $5.99');
        expect(result).toContain('Blue construction paper:');
        expect(result).toContain('8.5x11 size');
        expect(result).toContain('50 sheets per pack');
        expect(result).toContain('Scissors (safety, rounded tips)');
      });
    });

    describe('Performance and Memory Tests', () => {
      it('should handle large number of materials efficiently', () => {
        const manyMaterials = Array.from({ length: 1000 }, (_, i) => `item${i}`);
        const text = `Materials: ${manyMaterials.join(', ')}`;

        const start = Date.now();
        const result = extractMaterials(text);
        const duration = Date.now() - start;

        expect(result).toHaveLength(1000);
        expect(duration).toBeLessThan(100); // Should be very fast
      });

      it('should handle deeply nested material lists', () => {
        let nested = 'Materials: top level';
        for (let i = 0; i < 50; i++) {
          nested += `\n  Level ${i} materials: item${i}`;
        }

        const result = extractMaterials(nested);
        expect(result.length).toBeGreaterThan(0);
      });

      it('should not consume excessive memory', () => {
        const beforeMemory = process.memoryUsage().heapUsed;
        
        // Process a moderately large text
        const largeText = `Materials: ${Array.from({ length: 5000 }, (_, i) => `item${i}`).join(', ')}`;
        const result = extractMaterials(largeText);
        
        const afterMemory = process.memoryUsage().heapUsed;
        const memoryIncrease = afterMemory - beforeMemory;

        expect(result).toHaveLength(5000);
        expect(memoryIncrease).toBeLessThan(10 * 1024 * 1024); // Less than 10MB increase
      });
    });

    describe('Unicode and Internationalization', () => {
      it.skip('should handle Unicode characters correctly', () => {
        const unicode = `
          Materials: 📝 papier, ✏️ crayons, 📐 règle
          Matériel supplémentaire:
          - papier de construction 🏗️
          - marqueurs effaçables 🖊️
        `;

        const result = extractMaterials(unicode);
        
        // Should handle Unicode in material names
        expect(result.some(item => item.includes('📝'))).toBe(true);
        expect(result.some(item => item.includes('🏗️'))).toBe(true);
      });

      it('should handle right-to-left text', () => {
        const rtl = `
          Materials: ورق، أقلام، مسطرة
          مواد إضافية:
          - ألوان مائية
          - مقص آمن
        `;

        const result = extractMaterials(rtl);
        
        // Should not crash and return array
        expect(Array.isArray(result)).toBe(true);
      });

      it('should handle mixed scripts', () => {
        const mixed = `
          Materials: paper 紙, pencils 鉛筆, rulers 定規
          材料:
          - はさみ (scissors)
          - のり (glue)
        `;

        const result = extractMaterials(mixed);
        
        expect(Array.isArray(result)).toBe(true);
        expect(result.length).toBeGreaterThan(0);
      });
    });
  });

  describe('Integration Scenarios', () => {
    it.skip('should work with real-world lesson plan text', () => {
      const lessonPlan = `
        Grade 3 Mathematics - Fraction Introduction
        
        Learning Goals:
        - Students will understand fractions as parts of a whole
        - Students will identify halves, thirds, and quarters
        
        Materials:
        - Fraction circles (set of 30)
        - Paper plates (white, 9-inch diameter)
        - Colored markers or crayons
        - Rulers (30 cm)
        - Fraction worksheets (see appendix A)
        
        Activity 1: Fraction Circles
        Additional materials needed:
        - Masking tape
        - Chart paper
        
        Activity 2: Pizza Fractions
        Materials for this activity:
        - Construction paper (brown for crust, red for sauce)
        - Glue sticks
        - Safety scissors
        
        Homework materials:
        - Take-home fraction kit
        - Parent instruction sheet
      `;

      const result = extractMaterials(lessonPlan);

      // Should extract all materials from different sections
      expect(result).toContain('Fraction circles (set of 30)');
      expect(result).toContain('Paper plates (white, 9-inch diameter)');
      expect(result).toContain('Masking tape');
      expect(result).toContain('Chart paper');
      expect(result).toContain('Construction paper (brown for crust, red for sauce)');
      expect(result).toContain('Take-home fraction kit');
      expect(result).toContain('Parent instruction sheet');
      
      // Should not have duplicates
      const uniqueItems = [...new Set(result)];
      expect(result.length).toBe(uniqueItems.length);
    });

    it('should handle lesson plans with no materials', () => {
      const noMaterials = `
        Grade 5 Physical Education - Running Techniques
        
        Learning Goals:
        - Improve running form
        - Develop endurance
        
        Warm-up: Light jogging
        Main Activity: Sprint practice
        Cool-down: Stretching
        
        Assessment: Observe student form
      `;

      const result = extractMaterials(noMaterials);
      expect(result).toEqual([]);
    });

    it.skip('should extract from multi-day unit plans', () => {
      const unitPlan = `
        Week 1 Science Unit: Simple Machines
        
        Day 1 - Introduction
        Materials: lever examples, fulcrum blocks
        
        Day 2 - Pulleys
        Materials needed:
        - Rope (cotton, 10 feet)
        - Pulleys (fixed and movable)
        - Weights (various sizes)
        
        Day 3 - Inclined Planes
        Additional supplies:
        - Wooden ramps
        - Toy cars
        - Measuring tapes
        
        Day 4 - Assessment
        Materials: assessment rubric, observation forms
      `;

      const result = extractMaterials(unitPlan);

      expect(result).toContain('lever examples');
      expect(result).toContain('fulcrum blocks');
      expect(result).toContain('Rope (cotton, 10 feet)');
      expect(result).toContain('Pulleys (fixed and movable)');
      expect(result).toContain('Weights (various sizes)');
      expect(result).toContain('Wooden ramps');
      expect(result).toContain('Toy cars');
      expect(result).toContain('Measuring tapes');
      expect(result).toContain('assessment rubric');
      expect(result).toContain('observation forms');
    });
  });
});
